{
  "title": "Đà Lạt mưa, mình trốn trong nhà",
  "summary": "Trời mưa nên cả ngày nấp dưới mái hiên: ngắm nhà thờ, xem bảo tàng, rồi nhâm nhi cà phê và ăn tối ấm bụng.",
  "stops": [
    {
      "poi_id": "p3",
      "kind": "activity",
      "must_do_id": null,
      "note": "Nhà thờ Con Gà vẫn đứng hiên ngang dưới mưa, mình vào trong ngắm mái vòm và nghe mưa rơi ngoài cửa kính."
    },
    {
      "poi_id": "p11",
      "kind": "activity",
      "must_do_id": null,
      "note": "Dinh Bảo Đại III có mái che kín, vừa tránh mưa vừa xem đồ xưa, không ướt một sợi lông nào."
    },
    {
      "poi_id": "p179",
      "kind": "meal",
      "must_do_id": null,
      "note": "Trưa nay ăn bánh căn nóng hổi trong quán, ngon quá (so tasty) mà khỏi lo mưa tạt."
    },
    {
      "poi_id": "p23",
      "kind": "activity",
      "must_do_id": null,
      "note": "Lam Dong Museum mở cửa chiều, mình vào xem đồ cổ và nghe chuyện Đà Lạt xưa trong lúc mưa rả rích."
    },
    {
      "poi_id": "p49",
      "kind": "activity",
      "must_do_id": null,
      "note": "Tối đến Mây Lang Thang ngồi trong nhà nhâm nhi cà phê, nhìn phố mưa lấp lánh qua cửa kính."
    },
    {
      "poi_id": "p157",
      "kind": "meal",
      "must_do_id": null,
      "note": "Tối ăn nem nướng Bà Hùng trong quán ấm áp, no bụng rồi về ngủ ngon giữa tiếng mưa đêm."
    }
  ]
}
```

